<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/commerce-fixture.php';require __DIR__.'/catalog-fixture.php';
use Hostider\Commerce\{Services,HandoffPolicy};use Hostider\Core\Id;use Hostider\Core\Database\Migrator;use Hostider\Core\Http\HttpError;use Hostider\Core\Security\{Principal,AccessGrant,Crypto};use Hostider\Finance\{Currency,Money,Reconciliation};
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();$s=new Services($db,testConfig('test'));$admin=commerceAdmin($s);$buyer=commerceUser($s,'review');$other=commerceUser($s,'review-other');$assignment=$db->execute('SELECT id FROM identity_assignments WHERE user_id=? AND customer_id IS NULL LIMIT 1',[$admin['user']])->fetchColumn();$db->execute('INSERT INTO identity_grants(id,assignment_id,permission,customer_scope) VALUES (?,?,?,?)',[Id::uuid(),$assignment,'finance.approve',$buyer['customer']]);
$actor=new Principal('review-staff',['finance.approve'],staff:true,mfa:true,expiresAt:time()+600,verifiedAt:time(),grants:[new AccessGrant('finance.approve',[$buyer['customer']])]);$reconcile=new Reconciliation($db,$s->config,$s->finance);
$case=function(string $code='LATE_OR_EXCESS_PAYMENT')use($db,$s,$buyer,$actor): array{return $db->transaction(function()use($s,$buyer,$actor,$code): array{$s->finance->openWallet($buyer['customer'],new Currency('TRY'),$actor);$payment=$s->finance->recordTestCollection($buyer['customer'],new Money('100',new Currency('TRY')),Id::uuid(),$actor,Id::uuid());$id=$s->finance->reconcile($payment,$code,$actor,Id::uuid());return compact('payment','id');});};
test('Review reconciliation uses pure bound confirmation and immutable encrypted evidence',function()use($db,$s,$admin,$buyer,$actor,$case): void {
    $c=$case();$p=['case_id'=>$c['id'],'resolution'=>'CREDIT_WALLET','evidence'=>'Synthetic bank statement row verified against original receipt'];$before=$s->finance->repository->balance($s->finance->repository->wallet($buyer['customer'],false)['id']);$review=commercePrepare($s,$admin,'admin','reconciliation-resolve',$p,$buyer['customer']);same($before,$s->finance->repository->balance($s->finance->repository->wallet($buyer['customer'],false)['id']));same(403,raises(HttpError::class,fn()=>commerceExecute($s,$admin,'admin','reconciliation-resolve',$p,$buyer['customer'],$review['id'],false))->status);$result=commerceExecute($s,$admin,'admin','reconciliation-resolve',$p,$buyer['customer'],$review['id']);same('RESOLVED',$result['status']);same(409,raises(HttpError::class,fn()=>commerceExecute($s,$admin,'admin','reconciliation-resolve',$p,$buyer['customer'],$review['id']))->status);
    $row=$db->execute('SELECT * FROM finance_reconciliation_resolutions WHERE case_id=?',[$c['id']])->fetch();same(false,str_contains($row['evidence_encrypted'],$p['evidence']));same($p['evidence'],(new Crypto(base64_decode($s->config->key,true)))->decrypt($row['evidence_encrypted'],'reconciliation:'.$row['id']));same(hash('sha256',$p['evidence']),$row['evidence_sha256']);same($c['payment'],$db->execute('SELECT subject_id FROM finance_reconciliations WHERE id=?',[$c['id']])->fetchColumn());raises(PDOException::class,fn()=>$db->execute('DELETE FROM finance_reconciliation_resolutions WHERE id=?',[$row['id']]));
});
test('Review reconciliation rejects IDOR missing scope impersonation stale MFA evidence and policy gates',function()use($db,$s,$buyer,$other,$actor,$reconcile,$case): void {
    $c=$case();$call=fn($customer,$a,$e='Synthetic statement reviewed and matched')=>$db->transaction(fn()=>$reconcile->plan($c['id'],$customer,'CREDIT_WALLET',$e,$a));same(403,raises(HttpError::class,fn()=>$call($other['customer'],$actor))->status);$outsider=new Principal('other',['finance.approve'],staff:true,mfa:true,expiresAt:time()+600,verifiedAt:time(),grants:[new AccessGrant('finance.approve',[$other['customer']])]);same(404,raises(HttpError::class,fn()=>$call($other['customer'],$outsider))->status);same(422,raises(HttpError::class,fn()=>$call($buyer['customer'],$actor,'short'))->status);
    foreach([new Principal('no-scope',['finance.approve'],staff:true,mfa:true,expiresAt:time()+600,verifiedAt:time()),new Principal('stale',['finance.approve'],staff:true,mfa:true,expiresAt:time()+600,verifiedAt:time()-301,grants:$actor->grants),new Principal('impersonated',['finance.approve'],$buyer['customer'],staff:true,mfa:true,expiresAt:time()+600,verifiedAt:time(),impersonating:true)] as $bad){same(403,raises(HttpError::class,fn()=>$call($buyer['customer'],$bad))->status);}
    $fx=$case('FX_REFUND_POLICY_REQUIRED');same(409,raises(HttpError::class,fn()=>$db->transaction(fn()=>$reconcile->resolve($fx['id'],$buyer['customer'],'CREDIT_WALLET','Synthetic FX gate cannot be approved away',$actor,Id::uuid())))->status);
});
test('Review interrupted resolution rolls back and refund is reserved without external send',function()use($db,$s,$buyer,$actor,$reconcile,$case): void {
    $c=$case();raises(RuntimeException::class,fn()=>$db->transaction(function()use($reconcile,$c,$buyer,$actor): void{$reconcile->resolve($c['id'],$buyer['customer'],'RESERVE_ORIGINAL_REFUND','Synthetic statement verified before rollback',$actor,Id::uuid());throw new RuntimeException('Injected interruption');}));same(0,(int)$db->execute('SELECT COUNT(*) FROM finance_reconciliation_resolutions WHERE case_id=?',[$c['id']])->fetchColumn());same('100',$db->transaction(fn()=>$s->finance->repository->available($s->finance->repository->payment($c['payment']))));$result=$db->transaction(fn()=>$reconcile->resolve($c['id'],$buyer['customer'],'RESERVE_ORIGINAL_REFUND','Synthetic statement and original method checked',$actor,Id::uuid()));same(false,$result['external_refund_sent']);same('0',$db->transaction(fn()=>$s->finance->repository->available($s->finance->repository->payment($c['payment']))));
});
test('Review no-funds decision requires zero unallocated balance and never posts money',function()use($db,$s,$buyer,$actor,$reconcile,$case): void {
    $c=$case();same(409,raises(HttpError::class,fn()=>$db->transaction(fn()=>$reconcile->resolve($c['id'],$buyer['customer'],'REVIEW_NO_FUNDS','Synthetic receipt already allocated by verified operation',$actor,Id::uuid())))->status);$db->transaction(fn()=>$s->finance->creditWallet($buyer['customer'],$c['payment'],new Money('100',new Currency('TRY')),Id::uuid(),$actor,Id::uuid()));$before=(int)$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn();$result=$db->transaction(fn()=>$reconcile->resolve($c['id'],$buyer['customer'],'REVIEW_NO_FUNDS','Synthetic receipt already credited; zero residual independently verified',$actor,Id::uuid()));same(null,$result['effect_id']);same($before,(int)$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn());
});
test('Review parallel case resolution produces one wallet credit and one immutable decision',function()use($db,$buyer,$case): void {
    $c=$case();$children=[];for($i=0;$i<2;++$i){$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/review-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode(['case'=>$c['id'],'customer'=>$buyer['customer']])."\n");$children[]=[$p,$pipes];}foreach($children as [$p,$pipes]){same("READY\n",fgets($pipes[1]));}foreach($children as [$p,$pipes]){fwrite($pipes[0],"GO\n");fclose($pipes[0]);}$codes=[];foreach($children as [$p,$pipes]){$codes[]=stream_get_contents($pipes[1]);fclose($pipes[1]);same('',stream_get_contents($pipes[2]));fclose($pipes[2]);same(0,proc_close($p));}sort($codes);same(['200','409'],$codes);same(1,(int)$db->execute('SELECT COUNT(*) FROM finance_reconciliation_resolutions WHERE case_id=?',[$c['id']])->fetchColumn());same(1,(int)$db->execute('SELECT COUNT(*) FROM finance_wallet_entries WHERE reference=?',['reconciliation:'.$c['id']])->fetchColumn());
});
test('Review unrelated catalog change leaves customer finance confirmation valid',function()use($s,$buyer,$db): void {$p=['minor'=>'10'];$review=commercePrepare($s,$buyer,'client','attempt-create',$p,$buyer['customer']);catalogFixture($db);same('PENDING',commerceExecute($s,$buyer,'client','attempt-create',$p,$buyer['customer'],$review['id'])['status']);});
test('Review handoff eligibility is fail closed for test legacy manual refund and open gates',function(): void {
    $o=['id'=>'order','customer_id'=>'customer','payment_request_id'=>'bill','status'=>'READY_FOR_PROVISIONING','origin_environment'=>'production','refund_status'=>'NONE'];$b=['id'=>'bill','customer_id'=>'customer','order_id'=>'order','status'=>'PAID'];same(true,HandoffPolicy::evaluate($o,$b,['AUTO'],true)['eligible']);same(false,HandoffPolicy::evaluate($o,$b,['AUTO'],false)['eligible']);foreach(['test','staging','LEGACY_UNKNOWN'] as $env){same(false,HandoffPolicy::evaluate(array_replace($o,['origin_environment'=>$env]),$b,['AUTO'],true)['eligible']);}foreach(['REQUIRES_APPROVAL','CANCELLED','PARTIALLY_PAID'] as $state){same(false,HandoffPolicy::evaluate(array_replace($o,['status'=>$state]),$b,['AUTO'],true)['eligible']);}same(false,HandoffPolicy::evaluate($o,$b,['MANUAL'],true)['eligible']);same(false,HandoffPolicy::evaluate(array_replace($o,['refund_status'=>'PARTIAL']),$b,['AUTO'],true)['eligible']);same(false,HandoffPolicy::evaluate($o,array_replace($b,['status'=>'ISSUED']),['AUTO'],true)['eligible']);same(false,HandoffPolicy::evaluate($o,array_replace($b,['customer_id'=>'other']),['AUTO'],true)['eligible']);same(false,HandoffPolicy::evaluate($o,$b,['AUTO'],true)['dispatch_enabled']);
});
test('Review order environment provenance cannot be promoted by update',function()use($db): void {$row=$db->execute('SELECT id,origin_environment FROM orders LIMIT 1')->fetch();same(true,(bool)$row);raises(PDOException::class,fn()=>$db->execute('UPDATE orders SET origin_environment=? WHERE id=?',[$row['origin_environment']==='production'?'test':'production',$row['id']]));});
test('Review shared catalog and FX version fences block unseen writes and rollback lock timeout',function()use($db): void {
    foreach(['catalog','fx'] as $aggregate){$db->transaction(function()use($db,$aggregate): void {$before=(new \Hostider\Core\Database\VersionFence($db))->read($aggregate);$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/fence-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode(['aggregate'=>$aggregate]));fclose($pipes[0]);same('1205',stream_get_contents($pipes[1]));fclose($pipes[1]);same('',stream_get_contents($pipes[2]));fclose($pipes[2]);same(0,proc_close($p));same($before,(new \Hostider\Core\Database\VersionFence($db))->read($aggregate));});$db->transaction(fn()=>(new \Hostider\Core\Database\VersionFence($db))->advance($aggregate));}
});
runTests();
